import{z as E,x as p,o as t,c as B,q as s,j as r,D as e,d as i,s as l,S as o,b as m}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"稀疏图","description":"","frontmatter":{"title":"稀疏图","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sparse-graph.md","filePath":"cs/sparse-graph.md","lastUpdated":1791063341000}'),d={name:"cs/sparse-graph.md"};function A(h,a,c,C,S,f){const n=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=s('<h1 id="稀疏图" tabindex="-1">稀疏图 <a class="header-anchor" href="#稀疏图" aria-label="Permalink to &quot;稀疏图&quot;">​</a></h1><div class="epigraph"><p>$m$ 随 $n$ 近似线性时，任何 $\\Theta(n^2)$ 的表示或算法都在付不存在的边的账。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 整理</footer></div><p><a href="/cs/adj-list-matrix">上一课</a>对比了矩阵与表。<a href="/cs/adj-list-matrix">渐近记号</a>已经能写 \\(O(n+m)\\)。<a href="/cs/locality-principle">局部性原理</a>要求顺序扫真实存在的边。本课不重画两种结构。缺口是把<strong>稀疏</strong>写成工作假设：平面图、有界度数、随机图的常见区段里 \\(m=O(n)\\) 或 \\(O(n\\log n)\\)，邻接表（及压缩行存储）成为默认，矩阵只留给稠密或代数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每次分析都按最坏 \\(m=\\Theta(n^2)\\)，表的优点写不出来，BFS 也会被写成 \\(\\Theta(n^2)\\)。缺口不是新的指针类型，而是约定：主干算法用 \\(n\\) 与 \\(m\\) 两个参数，稀疏意味着 \\(m\\ll n^2\\)，实现不得把不存在的边扫一遍。</p><p><span class="marginnote">数字实例：100 万顶点、500 万边的社交图：邻接矩阵要 \\(10^{12}\\) 格，即使每格 1 字节也是 1 TB；邻接表或 CSR 只要 \\(n+m\\) 量级，几十 MB。这四个数量级的差距就是「稀疏」假设换成具体内存账的意义。</span></p><p>CSR：把所有出边拼成一个数组，另用 \\(n+1\\) 个偏移标记每顶点的段。枚举连续，空间仍 \\(\\Theta(n+m)\\)，无指针。这是表的数组化，针对稀疏。</p><p><span class="marginnote">术语翻译：CSR 就是把邻接表压平成两个数组：一个数组按顶点顺序存所有出边的终点，另一个数组存每个顶点那一段从哪开始。没有指针跳转，边在内存里是连续的，枚举一个顶点的邻居就像顺序读一段数组。</span></p><p><span class="marginnote">稀疏不是「边很少到没有结构」。社交图、网格、道路网都稀疏却仍有局部团。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明输入规模为 \\((n,m)\\)。建图用表或 CSR，拒绝为问边而分配 \\(n^2\\) 除非 \\(m\\) 已接近。需要 \\(O(1)\\) 问边时，对稀疏图用边散列，不用矩阵。</p>',11)),(t(),r(o,null,{default:e(()=>[l(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22m%20%E2%89%AA%20n%C2%B2%22%5D%20--%3E%20CSR%5B%22CSR%2F%E9%82%BB%E6%8E%A5%E8%A1%A8%22%5D%0A%20%20SP%20--%3E%20ALG%5B%22%E7%AE%97%E6%B3%95%E5%86%99%E6%88%90%20%CE%98(n%2Bm)%22%5D%0A%20%20DEN%5B%22m%20%3D%20%CE%98(n%C2%B2)%22%5D%20--%3E%20MAT%5B%22%E7%9F%A9%E9%98%B5%E5%8F%AF%E6%8E%A5%E5%8F%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=m("p",null,"度分布可以偏斜：少数顶点 \\(\\deg=\\Theta(n)\\)，表仍正确，只是这些顶点的枚举本身就 \\(\\Theta(n)\\)。稀疏指全局 \\(m\\)，不是每个度都小。建图时若预先知道 \\(m\\)，一次分配边数组，避免链表节点逐条堆分配。",-1)),(t(),r(o,null,{default:e(()=>[l(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E9%A1%B6%E7%82%B9%20v%22%5D%20--%3E%20OFF%5B%22offsets%5Bv%5D%20%E4%B8%8E%20offsets%5Bv%2B1%5D%20%E5%9C%88%E5%87%BA%E5%8C%BA%E9%97%B4%22%5D%0A%20%20OFF%20--%3E%20ARR%5B%22edges%20%E6%95%B0%E7%BB%84%E7%9A%84%E8%BF%9E%E7%BB%AD%E4%B8%80%E6%AE%B5%22%5D%0A%20%20ARR%20--%3E%20SCAN%5B%22%E9%A1%BA%E5%BA%8F%E6%9E%9A%E4%B8%BE%20v%20%E7%9A%84%E6%89%80%E6%9C%89%E5%87%BA%E8%BE%B9%22%5D%0A%20%20SCAN%20--%3E%20LC%5B%22%E6%97%A0%E6%8C%87%E9%92%88%E8%B7%B3%E8%BD%AC%EF%BC%8C%E7%BC%93%E5%AD%98%E5%8F%8B%E5%A5%BD%22%5D%0A%20%20LC%20--%3E%20BFS%5B%22%E5%85%A8%E5%9B%BE%20BFS%20%E6%80%BB%E6%97%B6%E9%97%B4%20%CE%98(n%2Bm)%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p>这张图回答的是：CSR 的一次邻居枚举在内存里长什么样、为什么顺序扫描换来了局部性——同一段数组大概率已在缓存行里，指针表则一跳一个冷地址。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 BFS/DFS/最短路的界一律带 \\(m\\)。稀疏假设让这些算法接近线性。稠密图用矩阵乘法或直接 \\(\\Theta(n^2)\\) 扫描可能更简单，那是另一分支，主干先走稀疏。</p><p><span class="marginnote">常见误区：初学者容易以为稀疏图要求每个顶点度数都小。稀疏说的是全局边数 \\(m\\) 远小于 \\(n^2\\)：一个明星节点可以有百万粉丝（度 \\(\\Theta(n)\\)），只要大部分顶点度数低，\\(m=O(n)\\) 仍然成立，邻接表照样是最优表示。</span></p><p>NUMA 与 cache：CSR 顺序扫边数组，空间局部性好于指针表，这是稀疏图在现代机器上的实现注脚，不改变 \\(\\Theta(n+m)\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入图稀疏化算法（cut sparsisifiers），不把「稀疏」写成矩阵里零的比例以外的随机矩阵理论。动态边更新下 CSR 重建有代价，动态图可用邻接动态数组。</p><p>后课默认：图是稀疏给出的，表示是表或 CSR。无环有向是再加一条约束，用来预备拓扑序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稀疏：\\(m\\) 远小于 \\(n^2\\)；复杂度必须显式带 \\(m\\)。</li><li>CSR 把邻接表收成连续数组，枚举吃局部性。</li><li>有向无环作为表示约束，下一课 DAG。</li><li>稀疏指全局 \\(m\\)，不是每个顶点度数都小。</li><li>出处：Cormen et al. 图算法章对 \\(n,m\\) 参数的用法。</li></ul>',10))])}const D=E(d,[["render",A]]);export{u as __pageData,D as default};
